#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct CheckFinding {
    /// What the finding is about, specific enough that an exception covers only this finding: `identity:{id}`,
    /// `identity:{id}:rule:{ruleId}`, `session:{id}`, `trust:{id}`, `role:{id}`, `campaign:{id}`, `request:{id}`, or
    /// `tenant:{id}:{condition}` for organization-wide settings.
    #[serde(rename = "subject")]
    pub subject: String,
    /// Plain text without names; readers with directory access see the subject's name next to it.
    #[serde(rename = "detail")]
    pub detail: String,
    /// Members this type does not declare.
    #[serde(flatten)]
    pub extra: Map<String, Value>,
}

/// The compliance center: automated checks over the IAM state (who has MFA, stale access, reviews, leavers,
/// privileged access, audit integrity, ...), mapped to the requirements of common frameworks. Tenants turn checks
/// into controls, evaluate them on a schedule, record exceptions with an expiry, and export signed evidence. Checks
/// only read, and they read outside any transaction (`ctx.store`), so an evaluation never holds the store's write
/// lock while it walks a large tenant; only the results are written, in one short transaction. Findings name their
/// subject by ID (`identity:{id}`); names are looked up when results are read, so stored results carry no personal
/// data beyond pseudonymous IDs.
/// TODO(port): a union or intersection type in TypeScript; JSON until ported.
pub type CheckStatus = Value;

